import copy
import pytest

from observation_validator import validate

BASE = {
    "resourceType": "Observation",
    "status": "final",
    "code": {"text": "Hemoglobin"},
    "subject": {"reference": "Patient/abc123"},
    "valueQuantity": {
        "value": 13.5,
        "unit": "g/dL",
        "system": "http://unitsofmeasure.example",
    },
    "referenceRange": {
        "low": {"value": 12.0, "unit": "g/dL",
                "system": "http://unitsofmeasure.example"},
        "high": {"value": 16.0, "unit": "g/dL",
                 "system": "http://unitsofmeasure.example"},
    },
}


def make(**overrides):
    res = copy.deepcopy(BASE)
    for key, val in overrides.items():
        if val is None:
            res.pop(key, None)
        else:
            res[key] = val
    return res


def paths(result):
    return [e["path"] for e in result["errors"]]


# ---------------------------------------------------------------- fixtures

def test_valid_fixture_with_range():
    result = validate(make())
    assert result["valid"], result["errors"]
    assert result["errors"] == []
    assert result["interpretation"] == "N"


def test_valid_fixture_without_range():
    result = validate(make(referenceRange=None))
    assert result["valid"], result["errors"]
    assert result["errors"] == []
    assert result["interpretation"] is None


# ------------------------------------------------- status / value matrix

@pytest.mark.parametrize("status", ["registered", "preliminary", "final", "amended"])
def test_status_matrix_value_present(status):
    result = validate(make(status=status))
    assert result["valid"], result["errors"]


@pytest.mark.parametrize("status", ["registered", "preliminary", "final", "amended"])
def test_status_matrix_value_absent(status):
    result = validate(make(status=status, valueQuantity=None))
    if status == "final":
        assert not result["valid"]
        assert "/valueQuantity" in paths(result)
    else:
        assert result["valid"], result["errors"]


# ------------------------------------------------------- range violations

def test_low_greater_than_high():
    result = validate(make(
        referenceRange={
            "low": {"value": 18.0, "unit": "g/dL"},
            "high": {"value": 16.0, "unit": "g/dL"},
        }))
    assert not result["valid"]
    assert "/referenceRange/high/value" in paths(result)


def test_low_equal_to_high():
    result = validate(make(
        referenceRange={
            "low": {"value": 16.0, "unit": "g/dL"},
            "high": {"value": 16.0, "unit": "g/dL"},
        }))
    assert not result["valid"]
    assert "/referenceRange/high/value" in paths(result)


def test_range_unit_mismatch():
    result = validate(make(
        referenceRange={
            "low": {"value": 12.0, "unit": "mg/L"},
            "high": {"value": 16.0, "unit": "g/dL"},
        }))
    assert not result["valid"]
    assert "/referenceRange/low/unit" in paths(result)


# --------------------------------------------------------- interpretation

def _rr(low=12.0, high=16.0):
    return {
        "low": {"value": low, "unit": "g/dL"},
        "high": {"value": high, "unit": "g/dL"},
    }


def test_interpretation_low():
    assert validate(make(valueQuantity={**BASE["valueQuantity"], "value": 5.0},
                         referenceRange=_rr()))["interpretation"] == "L"


def test_interpretation_normal():
    assert validate(make(valueQuantity={**BASE["valueQuantity"], "value": 14.0},
                         referenceRange=_rr()))["interpretation"] == "N"


def test_interpretation_high():
    assert validate(make(valueQuantity={**BASE["valueQuantity"], "value": 20.0},
                         referenceRange=_rr()))["interpretation"] == "H"


def test_interpretation_boundary_equality_is_normal():
    at_low = validate(make(valueQuantity={**BASE["valueQuantity"], "value": 12.0},
                           referenceRange=_rr()))
    at_high = validate(make(valueQuantity={**BASE["valueQuantity"], "value": 16.0},
                            referenceRange=_rr()))
    assert at_low["interpretation"] == "N"
    assert at_high["interpretation"] == "N"
    assert at_low["valid"] and at_high["valid"]


def test_no_interpretation_without_reference_range():
    result = validate(make(referenceRange=None))
    assert result["valid"]
    assert result["interpretation"] is None


def test_no_interpretation_when_range_invalid():
    result = validate(make(
        valueQuantity={**BASE["valueQuantity"], "value": 14.0},
        referenceRange={"low": {"value": 16.0, "unit": "g/dL"},
                        "high": {"value": 12.0, "unit": "g/dL"}}))
    assert not result["valid"]
    assert result["interpretation"] is None


# ------------------------------------------------------- field-level rules

@pytest.mark.parametrize("bad,status_path", [
    ("draft", True),
    (None, True),
])
def test_invalid_statuses(bad, status_path):
    result = validate(make(status=bad))
    assert not result["valid"]
    assert "/status" in paths(result)


@pytest.mark.parametrize("text", ["", None, 42])
def test_code_text_rules(text):
    code = {} if text is None else {"text": text}
    result = validate(make(code=code))
    assert not result["valid"]
    assert "/code/text" in paths(result)


@pytest.mark.parametrize("ref", [
    "Patient/", "Observation/9", "patient/1", "Patient/a b", "", 123,
])
def test_subject_reference_pattern(ref):
    result = validate(make(subject={"reference": ref}))
    assert not result["valid"]
    assert "/subject/reference" in paths(result)


def test_wrong_resource_type():
    result = validate({**copy.deepcopy(BASE), "resourceType": "Procedure"})
    assert not result["valid"]
    assert "/resourceType" in paths(result)


def test_value_quantity_numeric_check():
    result = validate(make(valueQuantity={"value": "13.5", "unit": "g/dL",
                                          "system": "http://unitsofmeasure.example"}))
    assert not result["valid"]
    assert "/valueQuantity/value" in paths(result)


def test_value_quantity_system_fixed():
    result = validate(make(valueQuantity={"value": 13.5, "unit": "g/dL",
                                          "system": "http://example.org/units"}))
    assert not result["valid"]
    assert "/valueQuantity/system" in paths(result)


def test_error_shape_has_pointer_paths():
    result = validate(make(valueQuantity=None))
    for err in result["errors"]:
        assert set(err) == {"path", "code", "message"}
        assert err["path"].startswith("/")
